export type DeviceChange = {
  deviceId: DeviceId
  table: string
  key: string
  value: string
  action: 'learned' | 'added' | 'updated' | 'selected' | 'expired'
}

export type HopFrame = {
  fromDevice: DeviceId
  toDevice: DeviceId
  egressInterface: string
  sourceMac: string
  destinationMac: string
  note?: string
}

export type SimulationStep = {
  order: number
  kind: 'frame' | 'packet' | 'decision'
  sourceDevice: DeviceId
  destinationDevice: DeviceId
  route: DeviceId[]
  ingressInterface: string
  egressInterface: string
  protocol: string
  osiLayer: string
  ethernet: { source: string; destination: string; note?: string; vlan?: string } | null
  network: { protocol: string; source: string; destination: string; ttl?: number } | null
  transport: { protocol: string; sourcePort?: string; destinationPort?: string; flags?: string } | null
  payload: string
  explanation: string
  deviceChanges: DeviceChange[]
  hopFrames?: HopFrame[]
  callout?: string
  encrypted?: boolean
}

export type Scenario = {
  id: 'dhcp' | 'arp-ping' | 'routing' | 'https' | 'vlan-routing' | 'dhcp-relay' | 'nat-pat' | 'traceroute' | 'trunk-fault' | 'stp-loop' | 'wifi-join' | 'stateful-firewall' | 'ip-sandbox'
    | 'ipv6-addressing' | 'ipv6-ndp' | 'ipv6-slaac' | 'ipv6-gateway' | 'ipv6-dual-stack' | 'ipv6-routing' | 'ipv6-nat64'
    | 'route-lpm' | 'troubleshooting' | 'wireless-rf'
  title: string
  subtitle: string
  objective: string
  outcome: string
  accent: string
  icon: string
  topology?: {
    zones: { left: { label: string; detail: string }; right?: { label: string; detail: string } }
    nodes?: Partial<Record<DeviceId, { name?: string; detail?: string }>>
    links?: [DeviceId, DeviceId][]
    visibleNodes?: DeviceId[]
  }
  networkPlusTopics?: string[]
  initialState: DeviceChange[]
  steps: SimulationStep[]
}

const change = (deviceId: DeviceId, table: string, key: string, value: string, action: DeviceChange['action'] = 'updated'): DeviceChange => ({ deviceId, table, key, value, action })
const learn = (mac: string, port: string, vlan = '10'): DeviceChange => change('switch', 'MAC address table', mac, `${port} · VLAN ${vlan}`, 'learned')
const arp = (deviceId: DeviceId, ip: string, mac: string): DeviceChange => change(deviceId, 'ARP cache', ip, mac, 'added')
const layer2 = (source: string, destination: string, note?: string, vlan?: string): SimulationStep['ethernet'] => ({ source, destination, note, vlan })
const ip = (source: string, destination: string, ttl?: number): SimulationStep['network'] => ({ protocol: 'IPv4', source, destination, ttl })
const udp = (sourcePort: string, destinationPort: string): SimulationStep['transport'] => ({ protocol: 'UDP', sourcePort, destinationPort })
const tcp = (sourcePort: string, destinationPort: string, flags: string): SimulationStep['transport'] => ({ protocol: 'TCP', sourcePort, destinationPort, flags })
const icmp = (message: string): SimulationStep['transport'] => ({ protocol: 'ICMP', flags: message })

function sequence(drafts: Omit<SimulationStep, 'order'>[]): SimulationStep[] {
  return drafts.map((step, index) => ({ ...step, order: index + 1 }))
}

