const ip6 = (source: string, destination: string, ttl = 64): SimulationStep['network'] => ({ protocol: 'IPv6', source, destination, ttl })
const icmpv6 = (flags: string): SimulationStep['transport'] => ({ protocol: 'ICMPv6', flags })
type PhaseStep = Omit<SimulationStep, 'order'>
function phaseStep(sourceDevice: DeviceId, destinationDevice: DeviceId, route: DeviceId[], protocol: string, source: string, destination: string, payload: string, explanation: string, options: Partial<PhaseStep> = {}): PhaseStep {
  const ipv6 = source.includes(':') || destination.includes(':')
  return {
    kind: options.kind ?? 'packet', sourceDevice, destinationDevice, route,
    ingressInterface: options.ingressInterface ?? 'Ethernet0', egressInterface: options.egressInterface ?? 'Simulated next hop',
    protocol, osiLayer: options.osiLayer ?? 'Layer 3 · Network', ethernet: options.ethernet === undefined ? layer2(devices[sourceDevice].mac, devices[destinationDevice].mac) : options.ethernet,
    network: options.network === undefined ? (ipv6 ? ip6(source, destination) : ip(source, destination)) : options.network,
    transport: options.transport === undefined ? (ipv6 ? icmpv6('Echo request') : icmp('Echo request')) : options.transport,
    payload, explanation, deviceChanges: options.deviceChanges ?? [],
    ...(options.hopFrames ? { hopFrames: options.hopFrames } : {}), ...(options.callout ? { callout: options.callout } : {}),
  }
}

