export const scenarios: Scenario[] = [...coreScenarios, ...courseScenarios, ...phaseTwoScenarios]

export function accumulatedChanges(scenario: Scenario, throughOrder: number): DeviceChange[] {
  const latest = new Map<string, DeviceChange>()
  for (const entry of scenario.initialState) latest.set(`${entry.deviceId}:${entry.table}:${entry.key}`, entry)
  for (const step of scenario.steps.slice(0, throughOrder)) {
    for (const entry of step.deviceChanges) latest.set(`${entry.deviceId}:${entry.table}:${entry.key}`, entry)
  }
  return [...latest.values()]
}
